// lab_flame.js
// 這是你的原始代碼「封印字串」，不管裡面有什麼特殊符號，都不會報錯
const mySecretCode = "";

const FlameLab = {
    open: function() {
        if (!document.getElementById('flame-lab-overlay')) {
            this.init();
        }
        document.getElementById('flame-lab-overlay').style.display = 'flex';
        document.body.style.overflow = 'hidden'; 
    },

    close: function() {
        document.getElementById('flame-lab-overlay').style.display = 'none';
        document.body.style.overflow = '';
    },

    init: function() {
        const modal = document.createElement('div');
        modal.id = 'flame-lab-overlay';
        // 建立全螢幕黑色遮罩
        modal.style.cssText = "position:fixed; top:0; left:0; width:100%; height:100%; background:#020617; z-index:99999; display:none; flex-direction:column;";
        
        // 建立關閉按鈕
        const closeBtn = document.createElement('div');
        closeBtn.innerHTML = "✕ CLOSE EXIT";
        closeBtn.style.cssText = "position:absolute; top:15px; right:20px; z-index:100000; color:#00f2ff; border:1.5px solid #00f2ff; padding:6px 12px; cursor:pointer; font-family:'Rajdhani',sans-serif; font-weight:bold; background:rgba(2,6,23,0.9); border-radius:4px; font-size:14px; box-shadow:0 0 15px rgba(0, 242, 255, 0.3);";
        closeBtn.onclick = () => this.close();

        // 建立一個獨立的虛擬視窗 (Iframe)
        const iframe = document.createElement('iframe');
        iframe.style.cssText = "width:100%; height:100%; border:none; background:#020617;";
        
        // 【核心】將封印字串翻轉回原始代碼並載入，保證 1:1 呈現
        // 使用數據傳輸協議 (Data URI) 直接載入
        iframe.src = "data:text/html;charset=utf-8;base64," + mySecretCode;
        
        modal.appendChild(closeBtn);
        modal.appendChild(iframe);
        document.body.appendChild(modal);
    }
};
